import{_ as a,c as s,o as t,a2 as i}from"./chunks/framework.BjuSUJps.js";const o="/assets/stack-up-x.D4zq0WiA.mp4",n="/assets/stack-up-x.D4zq0WiA.mp4",p="/assets/stack-up-morse.Ca7vfZ-O.mp4",v=JSON.parse('{"title":"Cipher Chain (Post #15) - Takeover Archive","description":"Post #15 escalated the NeukoAI ARG into a full cipher chain involving QR codes, Pastebins, classical cryptography, and a locked takeover archive.","frontmatter":{"title":"Cipher Chain (Post #15) - Takeover Archive","description":"Post #15 escalated the NeukoAI ARG into a full cipher chain involving QR codes, Pastebins, classical cryptography, and a locked takeover archive.","date":"2025-12-19","author":"@DendiRedemption","tags":["ARG","NeukoAI","GBOY","Cipher","Pastebin","ZIP","Lore"],"draft":false},"headers":[],"relativePath":"transmissions/posts/post-15.md","filePath":"transmissions/posts/post-15.md"}'),l={name:"transmissions/posts/post-15.md"};function r(c,e,h,d,u,g){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="cipher-chain-post-15-takeover-archive" tabindex="-1">Cipher Chain (Post #15) - Takeover Archive <a class="header-anchor" href="#cipher-chain-post-15-takeover-archive" aria-label="Permalink to &quot;Cipher Chain (Post #15) - Takeover Archive&quot;">​</a></h1><blockquote><p><strong>Debrief by <a href="https://x.com/DendiRedemption" target="_blank" rel="noreferrer">@DendiRedemption</a></strong></p></blockquote><p><strong>Post #15 (Dec 3, 2025):</strong> Video released by <a href="https://x.com/neukoai" target="_blank" rel="noreferrer">@NeukoAI</a> - <a href="https://x.com/neukoai/status/1996332652492943710" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1996332652492943710</a></p><p>Post #15 marked a shift from passive observation to an explicit <strong>cipher chain</strong>, forcing solvers to loop between video, external links, and classical encryption methods.</p><p><video controls width="100%"><source src="'+o+'" type="video/mp4"></video></p><hr><h2 id="the-post" tabindex="-1">The Post <a class="header-anchor" href="#the-post" aria-label="Permalink to &quot;The Post&quot;">​</a></h2><video controls width="100%"><source src="'+n+'" type="video/mp4"></video><p>At the timing of &quot;00:08&quot;, a <strong>QR code</strong> flashes briefly on screen.</p><hr><p><img src="https://raw.githubusercontent.com/dendiredemptionarc-svg/wiki/main/.gitbook/assets/QRBOX.png" alt="QRBOX"></p><h2 id="qr-code-→-pastebin-1" tabindex="-1">QR Code → Pastebin #1 <a class="header-anchor" href="#qr-code-→-pastebin-1" aria-label="Permalink to &quot;QR Code → Pastebin #1&quot;">​</a></h2><p>The QR code resolves to the following Pastebin:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://pastebin.com/YY7LYT0v</span></span></code></pre></div><p>Contents:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xgor lktik qke zcu ullykz luax  https://pastebin.com/srSMbcaM</span></span></code></pre></div><p>At first glance, the message appears opaque, but its structure strongly suggests a classical substitution cipher.</p><hr><h2 id="caesar-cipher-6" tabindex="-1">Caesar Cipher (-6) <a class="header-anchor" href="#caesar-cipher-6" aria-label="Permalink to &quot;Caesar Cipher (-6)&quot;">​</a></h2><p>Applying a <strong>Caesar shift of -6</strong> reveals:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rail fence key two offset four</span></span></code></pre></div><p>Rather than a plaintext message, this line provides <strong>explicit decryption parameters</strong> for the next step.</p><hr><h2 id="pastebin-2-–-locked" tabindex="-1">Pastebin #2 – Locked <a class="header-anchor" href="#pastebin-2-–-locked" aria-label="Permalink to &quot;Pastebin #2 – Locked&quot;">​</a></h2><p>The linked Pastebin is password-protected:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://pastebin.com/srSMbcaM</span></span></code></pre></div><p>With no password yet available, solvers were forced to return to the source: the video itself.</p><hr><h2 id="hidden-morse-code-in-the-video" tabindex="-1">Hidden Morse Code in the Video <a class="header-anchor" href="#hidden-morse-code-in-the-video" aria-label="Permalink to &quot;Hidden Morse Code in the Video&quot;">​</a></h2><p>Scene-by-scene inspection revealed subtle symbols in the top-left corner of the video:</p><p><video controls width="100%"><source src="'+p+`" type="video/mp4"></video></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-  .  /</span></span></code></pre></div><p>Interpreted as Morse code, the sequence resolves to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-..- -. / ..- . ----- .--. .--.</span></span></code></pre></div><p>Decoded output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XN UE0PP</span></span></code></pre></div><p>This string clearly does not resolve on its own, but matches the parameters revealed earlier.</p><hr><h2 id="rail-fence-cipher-key-2-offset-4" tabindex="-1">Rail Fence Cipher (Key: 2, Offset: 4) <a class="header-anchor" href="#rail-fence-cipher-key-2-offset-4" aria-label="Permalink to &quot;Rail Fence Cipher (Key: 2, Offset: 4)&quot;">​</a></h2><p>Using:</p><ul><li><strong>Rail Fence key:</strong> 2</li><li><strong>Offset:</strong> 4</li></ul><p>Decrypting <code>XN UE0PP</code> produces:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XEN0 PUP</span></span></code></pre></div><p>This serves as the <strong>password</strong> for Pastebin #2.</p><hr><h2 id="pastebin-2-–-unlocked" tabindex="-1">Pastebin #2 – Unlocked <a class="header-anchor" href="#pastebin-2-–-unlocked" aria-label="Permalink to &quot;Pastebin #2 – Unlocked&quot;">​</a></h2><p>Unlocked contents:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>it calls itself special, but the special thing is underneath.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GSVB ZIV MRSRORHN YFG DV YVMW GSVN DRGS SFNZMRGB</span></span></code></pre></div><p>The phrasing immediately points toward a specific gboyspecial.com wesbite.</p><hr><h2 id="gboyspecial-–-underneath-the-surface" tabindex="-1">GBOYSPECIAL – Underneath the Surface <a class="header-anchor" href="#gboyspecial-–-underneath-the-surface" aria-label="Permalink to &quot;GBOYSPECIAL – Underneath the Surface&quot;">​</a></h2><p>The line <em>“it calls itself special”</em> references:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[https://gboyspecial.com](https://www.gboyspecial.com/)</span></span></code></pre></div><p>Inspecting the site via DevTools reveals a console message:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>special</span></span>
<span class="line"><span>ZG93bmxvYWRzL3Rha2VvdmVyLnppcA==</span></span></code></pre></div><p>The encoded string is <strong>Base64</strong>.</p><p>Decoded result:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>downloads/takeover.zip</span></span></code></pre></div><p>Combined URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gboyspecial.com/downloads/takeover.zip</span></span></code></pre></div><hr><h2 id="takeover-zip-–-archive-discovery" tabindex="-1">takeover.zip – Archive Discovery <a class="header-anchor" href="#takeover-zip-–-archive-discovery" aria-label="Permalink to &quot;takeover.zip – Archive Discovery&quot;">​</a></h2><p>Inside the downloaded archive:</p><ul><li><code>final_payload_locked.zip</code></li><li><code>password.txt</code></li></ul><p><code>password.txt</code> contains the following numeric sequence:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>54 60 76 34 57 56 86 99 56</span></span></code></pre></div><p>At this point, the archive remains locked.</p><hr><p><img src="https://raw.githubusercontent.com/dendiredemptionarc-svg/wiki/main/.gitbook/assets/takeoverzip.png" alt="Takeoverzip files"></p><h2 id="atbash-cipher-–-narrative-as-instruction" tabindex="-1">Atbash Cipher – Narrative as Instruction <a class="header-anchor" href="#atbash-cipher-–-narrative-as-instruction" aria-label="Permalink to &quot;Atbash Cipher – Narrative as Instruction&quot;">​</a></h2><p>Returning to the earlier encrypted line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GSVB ZIV MRSRORHN YFG DV YVMW GSVN DRGS SFNZMRGB</span></span></code></pre></div><p>Applying <strong>Atbash cipher</strong> yields:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>THEY ARE NIHILISM BUT WE BEND THEM WITH HUMANITY</span></span></code></pre></div><p>This line functions as both lore and a direct technical hint.</p><hr><h2 id="nihilist-cipher-–-final-decryption" tabindex="-1">Nihilist Cipher – Final Decryption <a class="header-anchor" href="#nihilist-cipher-–-final-decryption" aria-label="Permalink to &quot;Nihilist Cipher – Final Decryption&quot;">​</a></h2><p>The message explicitly points to:</p><ul><li><strong>Cipher:</strong> Nihilist</li><li><strong>Key:</strong> <code>HUMANITY</code></li><li><strong>Ciphertext:</strong></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>54 60 76 34 57 56 86 99 56</span></span></code></pre></div><p>Using a standard Nihilist square with the key <em>HUMANITY</em>, the decrypted result is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LETHIMRUN</span></span></code></pre></div><hr><p><img src="https://raw.githubusercontent.com/dendiredemptionarc-svg/wiki/main/.gitbook/assets/nihilist.png" alt="nihilist"></p><h2 id="final-payload" tabindex="-1">Final Payload <a class="header-anchor" href="#final-payload" aria-label="Permalink to &quot;Final Payload&quot;">​</a></h2><p><code>LETHIMRUN</code> unlocks <code>final_payload_locked.zip</code>.</p><p>Inside is a collection of <strong>lore documents, images, and the full GBOY manifesto</strong>, marking the completion of Post #15’s cipher chain.</p><hr><h2 id="closing-notes" tabindex="-1">Closing Notes <a class="header-anchor" href="#closing-notes" aria-label="Permalink to &quot;Closing Notes&quot;">​</a></h2><p>Post #15 stands apart for its structure</p><p>Those who followed the full path didn’t just unlock files - they proved themselves part of the decoding crew.</p><p>[index0]</p><h2 id="related-posts" tabindex="-1">Related Posts <a class="header-anchor" href="#related-posts" aria-label="Permalink to &quot;Related Posts&quot;">​</a></h2><ul><li><a href="./post-14">Post #14: TBD</a> - Previous post</li><li><a href="./post-16">Post #16: Return to Sender</a> - Next post</li></ul>`,94)])])}const k=a(l,[["render",r]]);export{v as __pageData,k as default};
